mapper.select:
SELECT ac.*, am.model_name AS modelName, aa.name AS agentName, ap.prompt_title AS promptTitle FROM AI_CONVERSATION ac LEFT JOIN AI_MODEL_CONFIG am ON ac.model_id = am.id LEFT JOIN AI_AGENT aa ON ac.agent_id = aa.id LEFT JOIN AI_PROMPT ap ON ac.prompt_id = ap.id WHERE 1=1
AND ac.env_code = #{req.envCode}
AND ac.memory_id = #{req.memoryId}
AND ac.role = #{req.role}
ORDER BY ac.create_time DESC
